      "cevap": "Kılavuzlar ameliyat öncesi hazırlığı sunulabilir nitelikte, daha zayıf bir öneri olarak tanımlar. Yapılıp yapılmayacağı hekim değerlendirmesine ve takvime bağlıdır."
